def set_exception(self, exception):
        """Sets the exception of a ``Future.``"""
        self.exception = exception

def _handle_retry(self, resp):
        """Handle any exceptions during API request or
        parsing its response status code.

        Parameters:
        resp: requests.Response instance obtained during concerning request
            or None, when request failed

        Returns: True if should retry our request or raises original Exception
        """
        exc_t, exc_v, exc_tb = sys.exc_info()

        if exc_t is None:
            raise TypeError('Must be called in except block.')

        retry_on_exc = tuple(
            (x for x in self._retry_on if inspect.isclass(x)))
        retry_on_codes = tuple(
            (x for x in self._retry_on if isinstance(x, int)))

        if issubclass(exc_t, ZendeskError):
            code = exc_v.error_code
            if exc_t not in retry_on_exc and code not in retry_on_codes:
                six.reraise(exc_t, exc_v, exc_tb)
        else:
            if not issubclass(exc_t, retry_on_exc):
                six.reraise(exc_t, exc_v, exc_tb)

        if resp is not None:
            try:
                retry_after = float(resp.headers.get('Retry-After', 0))
                time.sleep(retry_after)
            except (TypeError, ValueError):
                pass

        return True

def _handle_retry(self, resp):
        """Handle any exceptions during API request or
        parsing its response status code.

        Parameters:
        resp: requests.Response instance obtained during concerning request
            or None, when request failed

        Returns: True if should retry our request or raises original Exception
        """
        if resp is None:
            raise Exception('API request failed')

        if resp.status_code == 429:
            raise Exception('API request rate limit exceeded')

        if resp.status_code == 400:
            raise Exception('API request failed with status code 400')

        if resp.status_code == 401:
            raise Exception('API request failed with status code 401')

        if resp.status_code == 403:
            raise Exception('API request failed with status code 403')

        if resp.status_code == 404:
            raise Exception('API request failed with status code 404')

        if resp.status_code == 500:
            raise Exception('API request failed with status code 500')

        if resp.status_code == 502:
            raise Exception('API request failed with status code 502')

        if resp.status_code == 503:
            raise Exception('API request failed with status code 503')

        if resp.status_code == 504:
            raise Exception('API request failed with status code 504')

        if resp.status_code == 520:
            raise Exception('API request failed with status code 520')

        if resp.status_code == 521:
