        if resp.status_code == 526:
            raise Exception('API request failed with status code 526')

        if resp.status_code == 527:
            raise Exception('API request failed with status code 527')

        return False

def getWindowTitle(self, hwnd):
        """ Gets the title for the specified window """
        length = User32.GetWindowTextLengthW(hwnd)
        if length > 0:
            buffer = ctypes.create_unicode_buffer(length + 1)
            User32.GetWindowTextW(hwnd, buffer, length + 1)
            return buffer.value
        else:
            return None

def _recv_thread(self):
        """
        Internal thread to iterate over source messages and dispatch callbacks.
        """
        for msg, metadata in self._source:
            if msg.msg_type:
                self._call(msg, **metadata)
        # Break any upstream iterators
        for sink in self._sinks:
            i = sink()
            if i is not None:
                i.breakiter()
        self._dead = True

def _recv_thread(self):
        """
        Internal thread to iterate over source messages and dispatch callbacks.
        """
        while True:
            try:
                msg = self.source.recv()
            except Exception as e:
                self.logger.exception(e)
                break
            self.dispatch(msg)

def _delete_fields(self):
        """
        Delete this object's attributes, including name and id
        """
        for key in self._json_dict.keys():
            if not key.startswith("_"):
                delattr(self, key)
        self._json_dict = {}
        self.id = None
        self.name = None

def _delete_fields(self):
        """
        Delete this object's attributes, including name and id
        """
        for field in self.fields:
            delattr(self, field)

def set_current_filename(self, filename, focus=True):
        """Set current filename and return the associated editor instance."""
        index = self.has_filename(filename)
        if index is not None:
            if focus:
                self.set_stack_index(index)
            editor = self.data[index].editor
            if focus:
                editor.setFocus()
            else:
                self.stack_history.remove_and_append(index)

            return editor

def set_current_filename(self, filename, focus=True):
        """Set current filename and return the associated editor instance."""
        if filename is None:
            return None
        if filename in self.editors:
            editor = self.editors[filename]
            if focus:
                editor.setFocus()
            return editor
        else:
            editor = self.create_editor(filename)
            self.editors[filename] = editor
            return editor

