def q(self, q, inputs=None, limit='', offset='', history=False):
    """ query
    """
    if inputs is None:
      inputs = {}
    if limit == '':
      limit = self.limit
    if offset == '':
      offset = self.offset
    if history:
      return self.history(q, inputs, limit, offset)
    else:
      return self.query(q, inputs, limit, offset)

def nose_selector(test):
    """Return the string you can pass to nose to run `test`, including argument
    values if the test was made by a test generator.

    Return "Unknown test" if it can't construct a decent path.

    """
    address = test_address(test)
    if address:
        file, module, rest = address

        if module:
            if rest:
                try:
                    return '%s:%s%s' % (module, rest, test.test.arg or '')
                except AttributeError:
                    return '%s:%s' % (module, rest)
            else:
                return module
    return 'Unknown test'

def nose_selector(test):
    """Return the string you can pass to nose to run `test`, including argument
    values if the test was made by a test generator.

    Return "Unknown test" if it can't construct a decent path.

    """
    if isinstance(test, nose.case.Test):
        return test.id()
    elif isinstance(test, nose.case.TestGenerator):
        return test.id()
    else:
        return "Unknown test"

