def _make_query_from_terms(self, terms, limit=None):
        """ Creates a query for dataset from decomposed search terms.

        Args:
            terms (dict or unicode or string):

        Returns:
            tuple of (TextClause, dict): First element is FTS query, second is parameters
                of the query. Element of the execution of the query is pair: (vid, score).

        """
        if isinstance(terms, six.string_types):
            terms = self._decompose_terms(terms)

        if not terms:
            return None, {}

        query = []
        params = {}
        for term in terms:
            if term.get('type') == 'phrase':
                query.append(self._make_phrase_query(term))
            else:
                query.append(self._make_term_query(term))

        if limit:
            query.append(self._make_limit_query(limit))

        return''.join(query), params

def match_type(mtype, patterns):
    """return True if mtype matches pattern"""
