def configure_timeindex(self):
        """ Construct a DateTimeIndex with the queried temporal resolution,
        start- and end_snapshot. """
        if self.start_snapshot is None:
            self.start_snapshot = self.snapshots[0]
        if self.end_snapshot is None:
            self.end_snapshot = self.snapshots[-1]
        self.timeindex = pd.date_range(
            start=self.start_snapshot,
            end=self.end_snapshot,
            freq=self.temporal_resolution,
            closed='left'
        )

