def packing_angle(self):
        """ Angle between CA-CB of knob and CA(h1)-CA(h2). Returns None if knob is GLY. """
        try:
            knob_vector = self.knob_residue['CB'] - self.knob_residue['CA']
        # exception for GLY residues (with no CB atom).
        except KeyError:
            return None
        hole_vector = self.hole_residues[2]['CA'] - self.hole_residues[1]['CA']
        return angle_between_vectors(knob_vector, hole_vector)

def packing_angle(self):
        """ Angle between CA-CB of knob and CA(h1)-CA(h2). Returns None if knob is GLY. """
        if self.resname == 'GLY':
            return None
        else:
            return self.get_angle(self.get_atom('CA'), self.get_atom('CB'), self.get_atom('CA', self.h1), self.get_atom('CA', self.h2))

def create_arj (archive, compression, cmd, verbosity, interactive, filenames):
    """Create an ARJ archive."""
    if compression == 'arj':
        if not cmd:
            cmd = 'arj'
        if not interactive:
            cmd +='-q'
        if verbosity:
            cmd +='-v'
        if filenames:
            cmd +='' +''.join(filenames)
        cmd +='' + archive
        return cmd
    else:
        raise ValueError('Unknown compression type: %s' % compression)

