def all_child_sprites(self):
        """returns all child and grandchild sprites in a flat list"""
        for sprite in self.sprites:
            for child_sprite in sprite.all_child_sprites():
                yield child_sprite
            yield sprite

def all_child_sprites(self):
        """returns all child and grandchild sprites in a flat list"""
        return [sprite for sprite in self.sprites()] + [child for child in self.children]

def calcDeviationLimits(value, tolerance, mode):
    """Returns the upper and lower deviation limits for a value and a given
    tolerance, either as relative or a absolute difference.

    :param value: can be a single value or a list of values if a list of values
        is given, the minimal value will be used to calculate the lower limit
        and the maximum value to calculate the upper limit
    :param tolerance: a number used to calculate the limits
    :param mode: either ``absolute`` or ``relative``, specifies how the
        ``tolerance`` should be applied to the ``value``.
    """
    if mode == "absolute":
        return value - tolerance, value + tolerance
    elif mode == "relative":
        return value * (1 - tolerance), value * (1 + tolerance)
    else:
        raise ValueError("mode must be either 'absolute' or'relative'")

def when_closed(self):
        """
        Returns a Deferred that callback()'s (with this Circuit instance)
        when this circuit hits CLOSED or FAILED.
        """
        if self.state in ['CLOSED', 'FAILED']:
            return defer.succeed(self)
        return self._when_closed.when_fired()

def vbkv_dumps(obj):
    """
    Serialize ``obj`` to a VBKV formatted ``bytes``.
    """
    return b''.join(
        (
            struct.pack(
                '>B',
                len(key)
            ),
            key,
            struct.pack(
                '>B',
                len(value)
            ),
            value
        )
        for key, value in obj.items()
    )

