def normalize_pipeline_name(name=''):
    """Translate unsafe characters to underscores."""
    normalized_name = name
    for bad in '\\/?%#':
        normalized_name = normalized_name.replace(bad, '_')
    return normalized_name

def normalize_pipeline_name(name=''):
    """Translate unsafe characters to underscores."""
    return re.sub(r'[^a-zA-Z0-9_]', '_', name)

def plot_lr(self, show_text=True, show_moms=True):
        """Plots the lr rate/momentum schedule"""
        phase_limits = [0]
        for nb_batch, phase in zip(self.nb_batches, self.phases):
            phase_limits.append(phase_limits[-1] + nb_batch * phase.epochs)
        if not in_ipynb():
            plt.switch_backend('agg')
        np_plts = 2 if show_moms else 1
        fig, axs = plt.subplots(1,np_plts,figsize=(6*np_plts,4))
        if not show_moms: axs = [axs]
        for i in range(np_plts): axs[i].set_xlabel('iterations')
        axs[0].set_ylabel('learning rate')
        axs[0].plot(self.iterations,self.lrs)
        if show_moms:
            axs[1].set_ylabel('momentum')
            axs[1].plot(self.iterations,self.momentums)
        if show_text:   
            for i, phase in enumerate(self.phases):
                text = phase.opt_fn.__name__
                if phase.wds is not None: text+='\nwds='+str(phase.wds)
                if phase.beta is not None: text+='\nbeta='+str(phase.beta)
                for k in range(np_plts):
                    if i < len(self.phases)-1:
                        draw_line(axs[k], phase_limits[i+1])
                    draw_text(axs[k], (phase_limits[i]+phase_limits[i+1])/2, text) 
        if not in_ipynb():
            plt.savefig(os.path.join(self.save_path, 'lr_plot.png'))

def plot_lr(self, show_text=True, show_moms=True):
        """Plots the lr rate/momentum schedule"""
        if not hasattr(self, 'lrs'):
            raise RuntimeError("Plotting before fitting has been run.")
        lrs = self.lrs
        iters = list(range(len(lrs)))
        if show_moms:
            moms = self.moms
            plt.plot(iters, moms, label='Momentum Schedule')
        plt.plot(iters, lrs, label='Learning Rate Schedule')
        if show_text:
            for x, y in zip(iters, lrs):
                plt.text(x, y, '%.4f' % y, ha='center', va='bottom', fontsize=10)
            if show_moms:
                for x, y in zip(iters, moms):
                    plt.text(x, y, '%.4f' % y, ha='center', va='top', fontsize=10)
        plt.xlabel("Iteration")
        plt.ylabel("Rate")
        plt.legend()
        plt.show()

def get_dir(path, dest, saltenv='base', template=None, gzip=None, **kwargs):
    """
    Used to recursively copy a directory from the salt master

    CLI Example:

    .. code-block:: bash

        salt '*' cp.get_dir salt://path/to/dir/ /minion/dest

    get_dir supports the same template and gzip arguments as get_file.
    """
    if template is None:
        template = __salt__['config.option']('file_client')
    if gzip is None:
        gzip = __salt__['config.option']('gzip_compress')
    if not os.path.isdir(dest):
        os.makedirs(dest)
    for root, dirs, files in os.walk(path):
        for f in files:
            src = os.path.join(root, f)
            dest = os.path.join(dest, os.path.relpath(src, path))
            if os.path.exists(dest):
                continue
            __salt__['cp.get_file'](src, dest, saltenv=saltenv, template=template, gzip=gzip, **kwargs)

def cookie_from_string(cookie_string, strict_cookies=False):
    """Parser for HTTP header set-cookie
    The return from this function will be used as parameters for
    django's response.set_cookie method. Because set_cookie doesn't
    have parameter comment, this cookie attribute will be ignored.

    :param  cookie_string: A string representing a valid cookie
    :param  strict_cookies: Whether to only accept RFC-compliant cookies
    :returns: A dictionary containing the cookie_string attributes
    """

    if strict_cookies:

        cookies = SimpleCookie(COOKIE_PREFIX + cookie_string)
        if not cookies.keys():
            return None
        cookie_name, = cookies.keys()
        cookie_dict = {k: v for k, v in cookies[cookie_name].items()
                       if v and k != 'comment'}
        cookie_dict['key'] = cookie_name
        cookie_dict['value'] = cookies[cookie_name].value
        return cookie_dict

    else:
        valid_attrs = ('path', 'domain', 'comment', 'expires',
                       'max_age', 'httponly', 'secure')

        cookie_dict = {}

        cookie_parts = cookie_string.split(';')
        try:
            key, value = cookie_parts[0].split('=', 1)
            cookie_dict['key'], cookie_dict['value'] = key, unquote(value)
        except ValueError:
            logger.warning('Invalid cookie: `%s`', cookie_string)
            return None

        if cookie_dict['value'].startswith('='):
            logger.warning('Invalid cookie: `%s`', cookie_string)
            return None

        for part in cookie_parts[1:]:
            if '=' in part:
                attr, value = part.split('=', 1)
                value = value.strip()
            else:
                attr = part
                value = ''

            attr = attr.strip().lower()
            if not attr:
                continue

            if attr in valid_attrs:
                if attr in ('httponly', 'secure'):
                    cookie_dict[attr] = True
                elif attr in 'comment':
                    # ignoring comment attr as explained in the
                    # function docstring
                    continue
                else:
                    cookie_dict[attr] = unquote(value)
            else:
                logger.warning('Unknown cookie attribute %s', attr)

        return cookie_dict

def aprint(*values, sep=None, end='\n', flush=False, streams=None, use_stderr=False, loop=None):
    """Asynchronous equivalent to *print*."""
    if streams is None:
        streams = [sys.stdout]
    if use_stderr:
        streams.append(sys.stderr)
    if loop is None:
        loop = asyncio.get_event_loop()
    coros = [loop.create_task(stream.write(sep.join(str(v) for v in values) + end)) for stream in streams]
    return asyncio.gather(*coros)

def set_encode_key_value(self, value, store_type):
        """Save the key value base on it's storage type."""
        self._store_type = store_type
        if store_type == PUBLIC_KEY_STORE_TYPE_HEX:
            self._value = value.hex()
        elif store_type == PUBLIC_KEY_STORE_TYPE_BASE64:
            self._value = b64encode(value).decode()
        elif store_type == PUBLIC_KEY_STORE_TYPE_BASE85:
            self._value = b85encode(value).decode()
        elif store_type == PUBLIC_KEY_STORE_TYPE_JWK:
            # TODO: need to decide on which jwk library to import?
            raise NotImplementedError
        else:
            self._value = value
        return value

def set_encode_key_value(self, value, store_type):
        """Save the key value base on it's storage type."""
        if store_type == 'file':
            self.set_file_key_value(value)
        elif store_type =='memory':
            self.set_memory_key_value(value)
        elif store_type =='redis':
            self.set_redis_key_value(value)
        else:
            raise Exception('Unknown storage type')

def padDigitalData(self, dig_data, n):
        """Pad dig_data with its last element so that the new array is a
        multiple of n.
        """
        n = int(n)
        l0 = len(dig_data)
        if l0 % n == 0:
            return dig_data  # no need of padding
        else:
            ladd = n - (l0 % n)
            dig_data_add = np.zeros(ladd, dtype="uint32")
            dig_data_add.fill(dig_data[-1])
            return np.concatenate((dig_data, dig_data_add))

def padDigitalData(self, dig_data, n):
        """Pad dig_data with its last element so that the new array is a
        multiple of n.
        """
        if len(dig_data) % n == 0:
            return dig_data
        else:
            return np.append(dig_data, dig_data[-1] * np.ones(n - len(dig_data) % n))

