def do_server(self, arg):
        """
        Usage:
          server on
          server off
          server restart
          server log
          server help
        """
        if arg['on']:
            self.server_on()
        elif arg['off']:
            self.server_off()
        elif arg['restart']:
            self.server_restart()
        elif arg['log']:
            self.server_log()
        else:
            self.help_server()

def do_server(self, arg):
        """
        Usage:
          server on
          server off
          server restart
          server log
          server help
        """
        if arg == 'on':
            self.server.start()
        elif arg == 'off':
            self.server.stop()
        elif arg =='restart':
            self.server.restart()
        elif arg == 'log':
            self.server.log()
        elif arg == 'help':
            print(self.server.help())
        else:
