def filter(fastq, sam, paired = False):
	""" 
	filter sequences that are shown to be mapped in the sam file
	reads not in sam file are in *.filtered.fastq
	reads that are in the sam file are in *.matched.fastq
	"""
	if paired:
		# paired end
		with open(fastq + ".filtered.fastq", "w") as out1, open(fastq + ".matched.fastq", "w") as out2:
			with open(fastq, "r") as f:
				for line in f:
					if line.startswith("@"):
						out1.write(line)
						out2.write(line)
					elif line.startswith("+"):
						out1.write(line)
						out2.write(line)
					elif line.startswith(">"):
						out1.write(line)
						out2.write(line)
					else:
						if line.strip() in sam:
							out2.write(line)
						else:
							out1.write(line)
	else:
		# single end
		with open(fastq + ".filtered.fastq", "w") as out1, open(fastq + ".matched.fastq", "w") as out2:
			with open(fastq, "r") as f:
				for line in f:
					if line.startswith("@"):
						out1.write(line)
						out2.write(line)
					elif line.startswith("+"):
						out1.write(line)
						out2.write(line)
					elif line.startswith(">"):
						out1.write(line)
						out2.write(line)
					else:
						if line.strip() in sam:
							out2.write(line)
						else:
							out1.write(line)

