    """ This will render an inline pagination for the posts related to the given topic.

    Usage::

        {% topic_pages_inline_list my_topic %}

    """
    data_dict = {
        'topic': topic,
    }

    pages_number = ((topic.posts_count - 1) // machina_settings.TOPIC_POSTS_NUMBER_PER_PAGE) + 1
    if pages_number > 5:
