def mkdir(self, remote_path):
        """Makes new directory on WebDAV server.
        More information you can find by link http://webdav.org/specs/rfc4918.html#METHOD_MKCOL

        :param remote_path: path to directory
        :return: True if request executed with code 200 or 201 and False otherwise.

        """
        directory_urn = Urn(remote_path, directory=True)

        try:
            response = self.execute_request(action='mkdir', path=directory_urn.quote())

            return response.status_code in (200, 201)
        except ResponseErrorCode as e:
            if e.code == 405:
                return True

            raise

def _check_arguments(self):
        """verify the argument of the default symbol and user provided parameters"""
        if self.argument_checked:
            return

        assert(self.symbol is not None)
        self.argument_checked = True

        # check if symbol contain duplicated names.
        _check_arguments(self.symbol)
        # rematch parameters to delete useless ones
        if self.allow_extra_params:
            if self.arg_params:
                arg_names = set(self.symbol.list_arguments())
                self.arg_params = {k : v for k, v in self.arg_params.items()
                                   if k in arg_names}
            if self.aux_params:
                aux_names = set(self.symbol.list_auxiliary_states())
                self.aux_params = {k : v for k, v in self.aux_params.items()
                                   if k in aux_names}

def _check_arguments(self):
        """verify the argument of the default symbol and user provided parameters"""
        if self.symbol is None:
            raise ValueError("symbol is None")
        if self.symbol not in self.symbol_list:
            raise ValueError("symbol is not in symbol_list")
        if self.interval is None:
            raise ValueError("interval is None")
        if self.interval not in self.interval_list:
            raise ValueError("interval is not in interval_list")
        if self.start_date is None:
            raise ValueError("start_date is None")
        if self.end_date is None:
            raise ValueError("end_date is None")
        if self.start_date > self.end_date:
            raise ValueError("start_date is greater than end_date")
        if self.start_date < self.start_date_limit:
            raise ValueError("start_date is less than start_date_limit")
        if self.end_date > self.end_date_limit:
            raise ValueError("end_date is greater than end_date_limit")

