    """
    This method is only an example! Replace it with a real nonce database.

    :param str key: the public key the nonce belongs to
    :param int nonce: the latest nonce
    """
    if not hasattr(app, 'example_nonce_db'):
        # store nonces as a pair {key: lastnonce}
        app.example_nonce_db = {}
    if not key in app.example_nonce_db:
        app.example_nonce_db[key] = nonce
        return 0
    else:
        oldnonce = copy.copy(app.example_nonce_db[key])
        app.example_nonce_db[key] = nonce
        return oldnonce

def tagReportCallback(llrpMsg):
    """Function to run each time the reader reports seeing tags."""
    global tagReport
    tags = llrpMsg.msgdict['RO_ACCESS_REPORT']['TagReportData']
    if len(tags):
        logger.info('saw tag(s): %s', pprint.pformat(tags))
    else:
        logger.info('no tags seen')
        return
    for tag in tags:
        tagReport += tag['TagSeenCount'][0]
        if "OpSpecResult" in tag:
            # copy the binary data to the standard output stream
            data = tag["OpSpecResult"].get("ReadData")
            if data:
                if sys.version_info.major < 3:
                    sys.stdout.write(data)
                else:
                    sys.stdout.buffer.write(data)                     # bytes
                logger.debug("hex data: %s", binascii.hexlify(data))

def do_attach(self, arg):
        """
        attach <target> [target...] - attach to the given process(es)
        """
        if self.cmdprefix:
            raise CmdError("prefix not allowed")
        targets = self.input_process_list( self.split_tokens(arg, 1) )
        if not targets:
            print("Error: missing parameters")
        else:
            debug = self.debug
            for pid in targets:
                try:
                    debug.attach(pid)
                    print("Attached to process (%d)" % pid)
                except Exception:
                    print("Error: can't attach to process (%d)" % pid)

def do_attach(self, arg):
        """
        attach <target> [target...] - attach to the given process(es)
        """
        if not arg:
            self.do_help('attach')
            return
        targets = arg.split()
        for target in targets:
            try:
                pid = int(target)
            except ValueError:
                self.do_help('attach')
                return
            try:
                self.attach(pid)
            except Exception as e:
                self.msg('attach failed: %s' % e)

