def statusfmt(status):
    """
    Format an exit status as text.
"""
    if status == 0:
        msg = 'exited ok'
    elif os.WIFSIGNALED(status):
        msg = 'died on '+signame(os.WTERMSIG(status))
    elif os.WIFEXITED(status) and os.WEXITSTATUS(status) > 0:
        msg = 'exited '+str(os.WEXITSTATUS(status))
    else:
        msg = 'unknown exit code 0x%04x' % (status,)
    if os.WCOREDUMP(status):
        msg += ' (core dumped)'
    return msg

def statusfmt(status):
    """
    Format an exit status as text.
"""
    if status == 0:
        return "OK"
    elif status == 1:
        return "ERROR"
    elif status == 2:
        return "WARNING"
    elif status == 3:
        return "CRITICAL"
    elif status == 4:
        return "UNKNOWN"
    else:
        return "UNKNOWN"

def iriToURI(iri):
    """Transform an IRI to a URI by escaping unicode."""
    # According to RFC 3987, section 3.1, "Mapping of IRIs to URIs"
    if isinstance(iri, bytes):
        iri = str(iri, encoding="utf-8")
    return iri.encode('ascii', errors='oid_percent_escape').decode()

def iriToURI(iri):
    """Transform an IRI to a URI by escaping unicode."""
    return quote(iri.encode('utf8'))

