def skip_whitespace(self):
        """Consume input until a non-whitespace character is encountered.

        The non-whitespace character is then ungotten, and the number of
        whitespace characters consumed is returned.

        If the tokenizer is in multiline mode, then newlines are whitespace.

        @rtype: int
        """

        skipped = 0
        while True:
            c = self._get_char()
            if c != ' ' and c != '\t':
                if (c != '\n') or not self.multiline:
                    self._unget_char(c)
                    return skipped
            skipped += 1

def skip_whitespace(self):
        """Consume input until a non-whitespace character is encountered.

        The non-whitespace character is then ungotten, and the number of
        whitespace characters consumed is returned.

        If the tokenizer is in multiline mode, then newlines are whitespace.

        @rtype: int
        """
        if self.multiline:
            return self.skip_whitespace_multiline()
        else:
            return self.skip_whitespace_singleline()

def _get_stddevs(self, C, stddev_types, num_sites):
        """
        Return total standard deviation.
        """
        stddevs = []
        for stddev_type in stddev_types:
            if stddev_type == 'total':
                stddevs.append(np.sqrt(np.sum(C)))
            elif stddev_type =='site':
                stddevs.append(np.sqrt(np.sum(C, axis=0)))
            elif stddev_type == 'bond':
                stddevs.append(np.sqrt(np.sum(C, axis=1)))
            elif stddev_type =='site-bond':
                stddevs.append(np.sqrt(np.sum(C, axis=0) + np.sum(C, axis=1)))
            elif stddev_type =='site-site':
                stddevs.append(np.sqrt(np.sum(C, axis=0) + np.sum(C, axis=1) - np.diag(C)))
            elif stddev_type =='site-site-bond':
                stddevs.append(np.sqrt(np.sum(C, axis=0) + np.sum(C, axis=1) - np.diag(C) + np.sum(C, axis=2)))
            else:
                raise ValueError('Unknown stddev type: {}'.format(stddev_type))
        return stddevs

def _installer(self, package_list, install_string=None):
        """Install operating system packages for the system.

        :param: package_list: ``list``
        :param install_string: ``str``
        """
        packages = ' '.join(package_list)

        if install_string is None:
            self.install_string = self.install_process[self.distro] % packages
        else:
            self.install_string = install_string

        output, outcome = self.shell.run_command(command=self.install_string)

        if outcome is False:
            raise IOError(output)

def _installer(self, package_list, install_string=None):
        """Install operating system packages for the system.

        :param: package_list: ``list``
        :param install_string: ``str``
        """
        if install_string is None:
            install_string = self.install_string
        for package in package_list:
            self.log.info("Installing %s" % package)
            self.run(install_string % package)

def update_combobox(self):
        """Recreates the combobox contents."""
        index = self.current_scheme_index
        self.schemes_combobox.blockSignals(True)
        names = self.get_option("names")
        try:
            names.pop(names.index(u'Custom'))
        except ValueError:
            pass
        custom_names = self.get_option("custom_names", [])

        # Useful for retrieving the actual data
        for n in names + custom_names:
            self.scheme_choices_dict[self.get_option('{0}/name'.format(n))] = n

        if custom_names:
            choices = names + [None] + custom_names
        else:
            choices = names

        combobox = self.schemes_combobox
        combobox.clear()

        for name in choices:
            if name is None:
                continue
            combobox.addItem(self.get_option('{0}/name'.format(name)), name)

        if custom_names:
            combobox.insertSeparator(len(names))

        self.schemes_combobox.blockSignals(False)
        self.schemes_combobox.setCurrentIndex(index)

