def find_splice(cigar):
    """Takes a cigar string and finds the first splice position as
    an offset from the start. To find the 5' end (read coords) of
    the junction for a reverse read, pass in the reversed cigar tuple"""

    offset = 0
    # a soft clip at the end of the read is taken as splicing
    # where as a soft clip at the start is not.
    if cigar[0][0] == 4:
        offset = cigar[0][1]
        cigar = cigar[1:]

    for op, bases in cigar:
        if op in (3, 4):
            # N or S: found the splice
            return offset
        elif op in (0, 2, 7, 8):
            # M, D, = or X: reference consuming
            offset += bases
        elif op in (1, 5, 6):
            # I, H, P: non-reference consuming
            continue
        else:
            raise ValueError("Bad Cigar operation: %i" % op)

    return False

def find_splice(cigar):
    """Takes a cigar string and finds the first splice position as
    an offset from the start. To find the 5' end (read coords) of
    the junction for a reverse read, pass in the reversed cigar tuple"""
    for i, (op, count) in enumerate(cigar):
        if op == 'S':
            return i
    return None

def identify_delim(txt):
	"""
	identifies delimiters and returns a count by ROW
	in the text file as well as the delimiter value (if any)
	The delim is determined if the count of delims is consistant
	in all rows.
	"""
	delim_count = {}
	delim = None
	for line in txt:
		line = line.strip()
		if line:
			if line[0] in delim_count:
				delim_count[line[0]] += 1
			else:
				delim_count[line[0]] = 1
	if len(delim_count) == 1:
		delim = delim_count.keys()[0]
	return delim_count, delim

