        @type domain: str

        @raises: ValueError If the locale contains invalid characters
        @return:
        """
        if not locale:
            raise ValueError("Locale is empty")
        if not domain:
            domain = self.default_domain
        if not domain:
            raise ValueError("Domain is empty")
        if not format:
            raise ValueError("Format is empty")
        if not resource:
            raise ValueError("Resource is empty")
        if not self.loader_exists(format):
            raise ValueError("Loader %s does not exist" % format)
        if not self.domain_exists(domain):
            raise ValueError("Domain %s does not exist" % domain)
        if not self.locale_exists(locale):
            raise ValueError("Locale %s does not exist" % locale)
        if not self.resource_exists(resource, locale, domain):
            self.resources[resource][locale][domain] = self.loader_get(format).load(resource, locale, domain)

