def has_implementation(self, number, arch, abi_list=()):
        """
        Pretty much the intersection of SimLibrary.has_implementation() and SimSyscallLibrary.get().

        :param number:      The syscall number
        :param arch:        The architecture being worked with, as either a string name or an archinfo.Arch
        :param abi_list:    A list of ABI names that could be used
        :return:            A bool of whether or not an implementation of the syscall is available
        """
        if not isinstance(arch, archinfo.Arch):
            arch = self.arch_from_name(arch)

        if not abi_list:
            abi_list = self.abis

        for abi in abi_list:
            if self.has_implementation(number, arch, abi):
                return True

        return False

def center_start(r, window_size):
  """
  Center a region on its start and expand it to window_size bases.

  :return: the new region.
  """
  return Region(r.chrom, r.start - window_size / 2, r.start + window_size / 2)

def _adjust_inserted_indices(inserted_indices_list, prune_indices_list):
        """Adjust inserted indices, if there are pruned elements."""
        if not prune_indices_list:
            return inserted_indices_list

        # Adjust inserted indices, if there are pruned elements.
        for i, inserted_indices in enumerate(inserted_indices_list):
            if not inserted_indices:
                continue
            for j, inserted_index in enumerate(inserted_indices):
                if inserted_index in prune_indices_list:
                    inserted_indices_list[i][j] = inserted_index - 1
        return inserted_indices_list

def convert_tags_to_dict(item):
    """
    Convert AWS inconvenient tags model of a list of {"Key": <key>, "Value": <value>} pairs
    to a dict of {<key>: <value>} for easier querying.

    This returns a proxied object over given item to return a different tags format as the tags
    attribute is read-only and we cannot modify it directly.
    """
    if hasattr(item, 'tags'):
        tags = item.tags
        if isinstance(tags, list):
            tags_dict = {}
            for kv_dict in tags:
                if isinstance(kv_dict, dict) and 'Key' in kv_dict and 'Value' in kv_dict:
                    tags_dict[kv_dict['Key']] = kv_dict['Value']
            return ObjectProxy(item, tags=tags_dict)
    return item

