def create_file_vdev(size, *vdevs):
    """
    Creates file based virtual devices for a zpool

    CLI Example:

    .. code-block:: bash

        salt '*' zpool.create_file_vdev 7G /path/to/vdev1 [/path/to/vdev2] [...]

    .. note::

        Depending on file size, the above command may take a while to return.

    """
    ret = OrderedDict()
    err = OrderedDict()

    _mkfile_cmd = salt.utils.path.which('mkfile')
    for vdev in vdevs:
        if os.path.isfile(vdev):
            ret[vdev] = 'existed'
        else:
            res = __salt__['cmd.run_all'](
                '{mkfile} {size} {vdev}'.format(
                    mkfile=_mkfile_cmd,
                    size=size,
                    vdev=vdev,
                ),
                python_shell=False,
            )
            if res['retcode'] != 0:
                if 'stderr' in res and ':' in res['stderr']:
                    ret[vdev] = 'failed'
                    err[vdev] = ":".join(res['stderr'].strip().split(':')[1:])
            else:
                ret[vdev] = 'created'
    if err:
        ret['error'] = err

    return ret

def create_file_vdev(size, *vdevs):
    """
    Creates file based virtual devices for a zpool

    CLI Example:

    .. code-block:: bash

        salt '*' zpool.create_file_vdev 7G /path/to/vdev1 [/path/to/vdev2] [...]

    .. note::

        Depending on file size, the above command may take a while to return.

    """
    vdevs = [vdev for vdev in vdevs if vdev]
    if not vdevs:
        raise CommandExecutionError("No vdevs specified")
    if len(vdevs) == 1:
        vdevs = vdevs * 2
    if len(vdevs) % 2!= 0:
        raise CommandExecutionError("Uneven number of vdevs specified")
    vdevs = [
        {
            "type": "file",
            "path": vdev,
        }
        for vdev in vdevs
    ]
    return create_vdev(size, *vdevs)

def path_yield(path):
    """Yield on all path parts."""
    for part in (x for x in path.strip(SEP).split(SEP) if x not in (None, '')):
        yield part

def path_yield(path):
    """Yield on all path parts."""
    for part in path.split('/'):
        yield part

def suffix(handlers, default=None, error='The requested suffix does not match any of those allowed'):
    """Returns a content in a different format based on the suffix placed at the end of the URL route
       should pass in a dict with the following format:

            {'[suffix]': action,
             ...
            }
    """
    def output_type(data, request, response):
        path = request.path
        handler = default
        for suffix_test, suffix_handler in handlers.items():
            if path.endswith(suffix_test):
                handler = suffix_handler
                break

        if not handler:
            raise falcon.HTTPNotAcceptable(error)

        response.content_type = handler.content_type
        return handler(data, request=request, response=response)
    output_type.__doc__ = 'Supports any of the following formats: {0}'.format(', '.join(function.__doc__ for function in
                                                                                        handlers.values()))
    output_type.content_type = ', '.join(handlers.keys())
    return output_type

def replace_command(command, broken, matched):
    """Helper for *_no_command rules."""
    new_cmds = get_close_matches(broken, matched, cutoff=0.1)
    return [replace_argument(command.script, broken, new_cmd.strip())
            for new_cmd in new_cmds]

def replace_command(command, broken, matched):
    """Helper for *_no_command rules."""
    if broken:
        return command.replace(matched, '')
    else:
        return command.replace(matched, 'no'+ matched)

