def list_storage(kwargs=None, conn=None, call=None):
    """
    .. versionadded:: 2015.8.0

    List storage accounts associated with the account

    CLI Example:

    .. code-block:: bash

        salt-cloud -f list_storage my-azure
    """
    if call != 'function':
        raise SaltCloudSystemExit(
            'The list_storage function must be called with -f or --function.'
        )

    if not conn:
        conn = get_conn()

    data = conn.list_storage_accounts()
    pprint.pprint(dir(data))
    ret = {}
    for item in data.storage_services:
        ret[item.service_name] = object_to_dict(item)
    return ret

def pluck(self, value, key=None):
        """
        Get a list with the values of a given key.

        :rtype: Collection
        """
        if key:
            return dict(map(lambda x: (data_get(x, key), data_get(x, value)), self.items))
        else:
            results = list(map(lambda x: data_get(x, value), self.items))

        return self.__class__(results)

def pluck(self, value, key=None):
        """
        Get a list with the values of a given key.

        :rtype: Collection
        """
        if key is None:
            return self.map(lambda x: x[value])
        else:
            return self.map(lambda x: x[key][value])

