        :return:  in JSON format.
        """
        MEvaluation.add_or_update(self.userinfo.uid, app_id, value)

        out_dic = {
            'eval0': MEvaluation.app_evaluation_count(app_id, 0),
            'eval1': MEvaluation.app_evaluation_count(app_id, 1)
        }

        return json.dump(out_dic, self)

def write_channel(self, out_data):
        """Generic handler that will write to both SSH and telnet channel.

        :param out_data: data to be written to the channel
        :type out_data: str (can be either unicode/byte string)
        """
        if self.ssh_channel:
            self.ssh_channel.write(out_data)
        if self.telnet_channel:
            self.telnet_channel.write(out_data)

def db_for_read(self, model, **hints):
        """
        If the app has its own database, use it for reads
        """
        if model._meta.app_label in self._apps:
            return getattr(model, '_db_alias', model._meta.app_label)
        return None

def invoke(self, function_name, raw_python=False, command=None, no_color=False):
        """
        Invoke a remote function.
        """

        # There are three likely scenarios for 'command' here:
        #   command, which is a modular function path
        #   raw_command, which is a string of python to execute directly
        #   manage, which is a Django-specific management command invocation
        key = command if command is not None else 'command'
        if raw_python:
            command = {'raw_command': function_name}
        else:
            command = {key: function_name}

        # Can't use hjson
        import json as json

        response = self.zappa.invoke_lambda_function(
            self.lambda_name,
            json.dumps(command),
            invocation_type='RequestResponse',
        )

        if 'LogResult' in response:
            if no_color:
                print(base64.b64decode(response['LogResult']))
            else:
                decoded = base64.b64decode(response['LogResult']).decode()
                formatted = self.format_invoke_command(decoded)
                colorized = self.colorize_invoke_command(formatted)
                print(colorized)
        else:
            print(response)

        # For a successful request FunctionError is not in response.
        # https://github.com/Miserlou/Zappa/pull/1254/
        if 'FunctionError' in response:
            raise ClickException(
                "{} error occurred while invoking command.".format(response['FunctionError'])
)

def invoke(self, function_name, raw_python=False, command=None, no_color=False):
        """
        Invoke a remote function.
        """
        if command is None:
            command = self.command
        if raw_python:
            command = self.raw_python_command
        if no_color:
            command = self.no_color_command
        command = command + [function_name]
        return self.invoke_command(command)

def get_rupture(oqparam):
    """
    Read the `rupture_model` file and by filter the site collection

    :param oqparam:
        an :class:`openquake.commonlib.oqvalidation.OqParam` instance
    :returns:
        an hazardlib rupture
    """
    rupture_model = oqparam.get_value('rupture_model')
    if rupture_model is None:
        return None
    rupture_model_file = oqparam.get_value('rupture_model_file')
    if rupture_model_file is None:
        return None
    rupture_model_file = os.path.join(oqparam.get_value('base_dir'),
                                      rupture_model_file)
    rupture_model_file = os.path.abspath(rupture_model_file)
    if not os.path.exists(rupture_model_file):
        raise OqParamError('rupture_model_file %s does not exist' %
                           rupture_model_file)
    rupture_model_file = os.path.abspath(rupture_model_file)
    if rupture_model == 'point_source':
        return PointRuptureFromUtm(rupture_model_file)
    elif rupture_model == 'complex_fault_surface':
        return ComplexFaultRuptureFromUtm(rupture_model_file)
    else:
        raise OqParamError('rupture_model %s not supported' % rupture_model)

def get_valid_byte(num, default):
        """check if the format of number is (num)(G|m|B) i.e 500GB, 200mb. 400
        etc.. """
        if num is None:
            return default
        num = num.strip()
        if num.endswith('GB'):
            return int(num[:-2]) * 1024 * 1024 * 1024
        elif num.endswith('MB'):
            return int(num[:-2]) * 1024 * 1024
        elif num.endswith('B'):
            return int(num[:-1])
        else:
            return default

def inserir(self, name):
        """Insert new network type and return its identifier.

        :param name: Network type name.

        :return: Following dictionary: {'net_type': {'id': < id >}}

        :raise InvalidParameterError: Network type is none or invalid.
        :raise NomeTipoRedeDuplicadoError: A network type with this name already exists.
        :raise DataBaseError: Networkapi failed to access the database.
        :raise XMLError: Networkapi failed to generate the XML response.
        """

        if not name:
            raise InvalidParameterError(
                'Network type name is invalid or none.')

        try:
            net_type = self.get_by_name(name)
            raise NomeTipoRedeDuplicadoError(
                'Network type with name %s already exists.' % name)
        except ObjectDoesNotExist:
            pass

        net_type = self.create(name)

        return {'net_type': {'id': net_type.id}}

def print_pack(document_loader,  # type: Loader
               processobj,       # type: CommentedMap
               uri,              # type: Text
               metadata          # type: Dict[Text, Any]
              ):  # type (...) -> Text
    """Return a CWL serialization of the CWL document in JSON."""
    packed = pack(document_loader, processobj, uri, metadata)
    if len(packed["$graph"]) > 1:
        return json_dumps(packed, indent=4)
    return json_dumps(packed["$graph"][0], indent=4)
